package com.insight.quantlife.tests;
import com.insight.quantlife.*;import com.insight.quantlife.TrackFilter.Point;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Local private feedback replay. stdout contains aggregates only. Never ships personal fixtures. */
public final class TrackFeedbackReplay {
 public static List<Point> read(String path)throws Exception{List<Point> raw=new ArrayList<>();try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(path),StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){String[] v=line.split("\t",-1);Point p=new Point();p.id=Long.parseLong(v[0]);p.time=Long.parseLong(v[1]);p.lat=Double.parseDouble(v[2]);p.lon=Double.parseDouble(v[3]);p.accuracy=Double.parseDouble(v[4]);p.speed=Double.parseDouble(v[5]);p.speedAccuracy=Double.parseDouble(v[6]);p.session=v[7];p.provider=v[8];p.eligible=Boolean.parseBoolean(v[9]);p.motionRms=Double.parseDouble(v[10]);p.motionAgeMs=Long.parseLong(v[11]);p.gpsAgeMs=(long)Double.parseDouble(v[12]);p.mocked=v.length>13&&Boolean.parseBoolean(v[13]);raw.add(p);}}return raw;}
 private static long fingerprint(List<Point> raw){long h=7;for(Point p:raw){h=31*h+p.id;h=31*h+p.time;h=31*h+Double.doubleToLongBits(p.lat);h=31*h+Double.doubleToLongBits(p.lon);h=31*h+Double.doubleToLongBits(p.accuracy);h=31*h+Double.doubleToLongBits(p.speed);h=31*h+Double.doubleToLongBits(p.motionRms);h=31*h+p.motionAgeMs;h=31*h+(p.breakBefore?1:0);}return h;}
 public static void main(String[] args)throws Exception{List<Point> raw=read(args[0]);long rawHash=fingerprint(raw);java.text.SimpleDateFormat df=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);df.setTimeZone(TimeZone.getTimeZone("Asia/Shanghai"));Map<String,List<Point>> days=new TreeMap<>();for(Point p:raw)days.computeIfAbsent(df.format(new Date(p.time)),k->new ArrayList<>()).add(p);
 try(PrintWriter file=new PrintWriter(args[1],"UTF-8")){for(Map.Entry<String,List<Point>> day:days.entrySet()){for(String mode:new String[]{"D","fusion"}){long start=System.nanoTime();List<Point> out=mode.equals("D")?TrackVariants.apply(day.getValue()):TrackFusion.apply(day.getValue());int moving=0,stop=0,unknown=0,isolated=0;for(int i=0;i<out.size();i++){Point p=out.get(i);if(p.motionState.equals("moving"))moving++;else if(p.motionState.equals("stationary_estimate"))stop++;else unknown++;if((i==0||!TrackVariants.connected(out.get(i-1),p))&&(i+1==out.size()||!TrackVariants.connected(p,out.get(i+1))))isolated++;file.printf(Locale.US,"%s\t%s\t%d\t%d\t%.9f\t%.9f\t%.3f\t%s\t%s\t%s\t%s%n",day.getKey(),mode,p.id,p.time,p.lat,p.lon,p.accuracy,p.breakBefore,p.motionState,p.session,p.provider);}
 Map<Long,Point> original=new HashMap<>();for(Point p:day.getValue())original.put(p.id,p);long last=0;for(int i=0;i<out.size();i++){Point p=out.get(i),source=original.get(p.id);if(source==null||source.time!=p.time||!Double.isFinite(p.lat)||!Double.isFinite(p.lon)||p.time<last)throw new AssertionError("Replay invented, reordered or corrupted an observation");last=p.time;if(mode.equals("fusion")&&(p.mocked||!p.eligible))throw new AssertionError("Excluded fix restored");if(mode.equals("fusion")&&i>0&&(p.motionState.equals("uncertain")||out.get(i-1).motionState.equals("uncertain"))&&TrackVariants.connected(out.get(i-1),p))throw new AssertionError("Uncertainty contributed mileage");}
 if(rawHash!=fingerprint(raw))throw new AssertionError("Replay mutated private source");
 System.out.printf(Locale.US,"%s %s raw=%d points=%d moving=%d stop=%d unknown=%d gaps=%d isolated=%d meters=%.1f ms=%d invariants=PASS%n",day.getKey(),mode,day.getValue().size(),out.size(),moving,stop,unknown,TrackVariants.gaps(out),isolated,TrackVariants.meters(out),(System.nanoTime()-start)/1000000);
 for(int hour=0;hour<24;hour++)if(day.getKey().equals("2026-10-17")&&mode.equals("fusion")){List<Point> h=new ArrayList<>();for(Point p:out)if((p.time/3600000+8)%24==hour)h.add(p);if(!h.isEmpty())System.out.printf(Locale.US,"hour=%02d points=%d meters=%.1f gaps=%d%n",hour,h.size(),TrackVariants.meters(h),TrackVariants.gaps(h));}
 }}}
 }
}
